VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: begins with a vowel, or starts with "xr" / "yt".
    if word[0] in VOWELS or word.startswith("xr") or word.startswith("yt"):
        return word + "ay"

    # Find where the leading consonant cluster ends.
    i = 0
    while i < len(word):
        c = word[i]
        if c in VOWELS:
            break
        # Rule 3: "qu" (with any preceding consonants) is part of the cluster.
        if c == "q" and i + 1 < len(word) and word[i + 1] == "u":
            i += 2
            break
        # Rule 4: "y" is a vowel once it follows at least one consonant.
        if c == "y" and i > 0:
            break
        # Otherwise a consonant (including a leading "y"); move it.
        i += 1

    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())
